def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * (w // 3) for _ in range(h // 3)]
    # The non-noise color is represented by the cell in each 3x3 block
    # with the strongest local agreement.
    for br in range(h // 3):
        for bc in range(w // 3):
            block = [grid[r][c]
                     for r in range(br * 3, br * 3 + 3)
                     for c in range(bc * 3, bc * 3 + 3)]
            counts = {v: block.count(v) for v in set(block)}
            # Preserve only a distinct color that forms a majority patch.
            color, count = max(counts.items(), key=lambda x: x[1])
            if color not in (0, 5) and count >= 5:
                out[br][bc] = color
    return out
